function amj(array$v,int$c=200):never{http_response_code($c);header('Content-Type: application/json; charset=utf-8');echo json_encode($v);exit;}function amn($v):string{return strtolower(trim((string)$v));}function amt(array$v,array$keys,string$f=''):string{foreach($keys as$k){$x=$v[$k]??null;if(is_scalar($x)&&trim((string)$x)!=='')return trim((string)$x);}return$f;}function amd($v):string{return wow_timestamp_to_string($v??'');}function aml(string$v):string{return ucwords(str_replace('_',' ',$v));}function am_source(string$v):string{return match(amn($v)){'passenger_app','passenger_mobile_app'=>'passenger_app','passenger_website','passenger_web'=>'passenger_website','driver_app','driver_mobile_app'=>'driver_app','driver_website','driver_web'=>'driver_website','admin_website','admin_web'=>'admin_website',default=>'unknown'};}function am_provider(string$v):string{$n=amn($v);return match($n){'google','google.com'=>'google.com','phone','phone_otp'=>'phone',default=>'password'};}function am_source_label(string$v):string{return match($v){'passenger_app'=>'Passenger Mobile App','passenger_website'=>'Passenger Website','driver_app'=>'Driver Mobile App','driver_website'=>'Driver Website','admin_website'=>'Admin Website',default=>'Source unavailable'};}function am_provider_label(string$v):string{return match($v){'google.com'=>'Google','phone'=>'Phone OTP',default=>'Email and Password'};}
